--同步账套
	"PORTFOLIO", 
	"BOOKNBDAYS", 
	"CLASSID", 
	"DEFAULTSECACCT", 
	"INCEPTIONDATE", 
	"JZGYFLAG", 
	"LASTACTIVEDATE", 
	"LASTGLCLOSE", 
	"LASTTRANCLOSE", 
	"CURRENCYCODE", 
	"LOTSELECTION", 
	"NAVPRECISION", 
	"NEXTGLCLOSE", 
	"NEXTTRANCLOSE", 
	"NEXTYEALCLOSE", 
	"PORT_NAME", 
	"PORTFOLIOTYPE", 
	"SHORTCODE", 
	"SHORTNAME", 
	"SINGLELOT", 
	"SYZFEFLAG", 
	"TRADESETTLELEDGER", 
	"WKNDVALUATIONCLOSE", 
	"GLGROUP", 
	"CHARTNUMBER", 
	"HOLIDAYSD", 
	"MANAGERGROUP", 
	"PORTFOLIOCLIENT", 
	"PROVINCE", 
	"CREATE_TIME", 
	"CREATE_DEPT", 
	"UPDATE_TIME", 
	"UPDATE_USER", 
	"CREATE_USER" 
 )
	select
 jyt.BOOKSET_ID as PORTFOLIO,
 0 as BOOKNBDAYS,
 0 as CLASSID,
 0 as DEFAULTSECACCT,
 jyt.START_DATE as INCEPTIONDATE,
 0 as JZGYFLAG,
 sysdate as LASTACTIVEDATE,
 jyt.START_DATE as LASTGLCLOSE,
 jyt.START_DATE as LASTTRANCLOSE,
 jyt.STANDARD_CCY as CURRENCYCODE,
 1 as LOTSELECTION,
 3 as NAVPRECISION,
 jyt.START_DATE as NEXTGLCLOSE,
 jyt.START_DATE as NEXTTRANCLOSE,
 jyt.START_DATE as NEXTYEALCLOSE,
 jyt.BOOKSET_FULLNAME as PORT_NAME,
 0 as PORTFOLIOTYPE,
 jyt.BOOKSET_ID as SHORTCODE,
 jyt.BOOKSET_NAME as SHORTNAME,
 'Y' as SINGLELOT,
 0 as SYZFEFLAG,
 0 as TRADESETTLELEDGER,
 0 as WKNDVALUATIONCLOSE,
 0 as GLGROUP,
 jyt.BOOKSET_ID_TMPL as CHARTNUMBER,
 jyt.CALENDAR_ID as HOLIDAYSD,
 1 as MANAGERGROUP,
 1 as PORTFOLIOCLIENT,
 1 as PROVINCE,
 sysdate as CREATE_TIME,
 '' as CREATE_DEPT,
 sysdate as UPDATE_TIME,
 'system' as UPDATE_USER,
 'system' as CREATE_USER
from
(select
  distinct
  bb.BOOKSET_ID,
  bb.STANDARD_CCY,
  bb.BOOKSET_ID_TMPL,
  bb.START_DATE,
  bb.BOOKSET_FULLNAME,
  bb.BOOKSET_NAME,
  fp.CALENDAR_ID
  from BOK_BOOKSET bb, FIN_PRODUCT fp
  where bb.BOOKSET_ID=fp.FINPROD_ID) jyt
;


