--创建证券账户
  ACCTID,
  ACCTCODE,
  ACCTDESC,
  PORTFOLIO,
  GLGROP,
  BROKERCODE,
  CREATE_TIME,
  UPDATE_TIME,
  UPDATE_USER,
  CREATE_USER
)
select 
  SecAcct_ID_SEQ.nextval as ACCTID,
  'SECACCT' || PORTFOLIO as ACCTCODE,
  'SECACCT' || PORTFOLIO as ACCTDESC,
  PORTFOLIO as PORTFOLIO,
  1 as GLGROP,
  (select BROKERID from JXS_BROKER where rownum=1) as BROKERCODE,
  sysdate as CREATE_TIME,
  sysdate as UPDATE_TIME,
  'system' as UPDATE_USER,
  'system' as CREATE_USER
  from
(select PORTFOLIO from JXS_PORTFOLIO_HDR) tb1;


--更新产品的默认证券账户
update JXS_PORTFOLIO_HDR js set js.DEFAULTSECACCT=(select jb.ACCTID from JXB_SECACCT jb where js.PORTFOLIO=jb.PORTFOLIO);


--同步银行信息
  "BANKID",
  "COUNTRY",
	"ADDRESS", 
	"BANKCODE", 
	"BANKDESC", 
	"CONTRACTOR", 
	"PHONEFAX", 
	"PHONENUM", 
	"CREATE_TIME", 
	"CREATE_DEPT", 
    "UPDATE_TIME", 
	"UPDATE_USER", 
	"CREATE_USER" 
)
select 
	jyt.BANK_DEP as BANKID,
	'CN' as COUNTRY,
	'' as ADDRESS,
	jyt.BANK_DEP as BANKCODE,
	jyt.BANK_DEP as BANKDESC,
	'' as CONTRACTOR,
	'' as PHONEFAX,
	'' as PHONENUM,
	sysdate as CREATE_TIME,
	'' as CREATE_DEPT,
	sysdate as UPDATE_TIME,
	'system' as UPDATE_USER,
	'system' as CREATE_USER
from 
(select distinct BANK_DEP from STL_CAPACCT_INFO where BANK_DEP is not null) jyt;


--银行现金账户
	"BK_ACCT_NO", 
	"ACCOUNTTYPE", 
	"BANKDESC", 
	"CASHGLCODE", 
	"CASHREALFXGNLS", 
	"CASHTRUNCATIONGAIN", 
	"CASHTRUNCATIONLOSS", 
	"CASHUNREALFXGNLS", 
	"CASHUNREALFXOFFSET", 
	"DEFAULTOFFSET",  
	"EXTERNALACCTNUMBER", 
	"INTCSHFLWMASTERREC", 
	"LAST_BAL_DATE", 
	"LAST_BALANCE", 
	"CURRENCYCODE", 
	"LASTCLOSE", 
	"NEXTCLOSE",  
	"STATUS", 
	"BANKID", 
	"PORTFOLIO", 
	"SECACCTCODE", 
	"DEFAULTPORT",
	"STRUCTURE",
	"REASON",
	"ODCSHFLWMASTERREC",
	"SEATNUMBER",
	"CREATE_TIME", 
	"CREATE_DEPT", 
	"UPDATE_TIME", 
	"UPDATE_USER", 
	"CREATE_USER"
   )
select 
  BkCashAcct_ID_SEQ.nextval as BK_ACCT_NO,
  0 as ACCOUNTTYPE,
  jyt.ACCT_NAME as BANKDESC,
  (CASE jyt.CCY 
    when 'CNY' then '10020101'
    when 'USD' then '10020102'
    when 'EUR' then '10020103'
    when 'GBP' then '10020104'
    when 'CAD' then '10020105'
    when 'HKD' then '10020107'
    when 'CHF' then '10020108'
    when 'JPY' then '10020109'
    when 'AUD' then '10020110'
    when 'SGD' then '10020111'
    when 'RUB' then '10020112'
    else '10020101' end
  ) as CASHGLCODE,
  '61120101' as CASHREALFXGNLS,
  '' as CASHTRUNCATIONGAIN,
  '' as CASHTRUNCATIONLOSS,
  '61120101' as CASHUNREALFXGNLS,
  '' as CASHUNREALFXOFFSET,
  '61120101' as DEFAULTOFFSET,
  jyt.ACCT_NO as EXTERNALACCTNUMBER,
  0 as INTCSHFLWMASTERREC,
  sysdate as LAST_BAL_DATE,
  0 as LAST_BALANCE,
  jyt.CCY as CURRENCYCODE,
  sysdate as LASTCLOSE,
  sysdate as NEXTCLOSE,
  1 as STATUS,
  jyt.BANK_DEP as BANKID,
  jyt.BOOKSET_ID as PORTFOLIO,
  jyt.secacctid as SECACCTCODE,
  0 as DEFAULTPORT,
  0 as STRUCTURE,
  0 as DEFAULTPORT,
  0 as REASON,
  jyt.ACCT_NO as SEATNUMBER,
  sysdate as CREATE_TIME,
  '' as CREATE_DEPT,
  sysdate as UPDATE_TIME,
  'system' as UPDATE_USER,
  'system' as CREATE_USER
  from
(select 
  scc.ACCT_NO,
  scc.ACCT_NAME,
  bbci.BOOKSET_ID,
  scc.BANK_DEP,
  scc.CCY,
  jsec.ACCTID as secacctid
  from STL_CAPACCT_INFO scc, BOK_BOOKSET_CAPACCT_INFO bbci, JXB_SECACCT jsec
  where scc.ACCT_NO=bbci.ACCT_NO and jsec.portfolio=bbci.BOOKSET_ID) jyt;

  
  
